import { useState, type FormEvent } from 'react';
import {
  ZONES,
  ZONE_LABELS,
  activeChips,
  withoutChip,
  type ChipKey,
  type SearchCriteria,
  type Zone,
} from '../../lib/search';
import styles from './FilterChips.module.css';

interface FilterChipsProps {
  criteria: SearchCriteria;
  onChange: (next: SearchCriteria) => void;
}

/** Las cinco opciones del formulario, en el orden fijo de la spec §3. */
const FIELD_OPTIONS: { key: ChipKey; label: string }[] = [
  { key: 'partNumber', label: 'Ref' },
  { key: 'brand', label: 'Marca' },
  { key: 'minQuantity', label: 'Qty mín' },
  { key: 'zone', label: 'Zona' },
  { key: 'maxLeadTimeDays', label: 'Lead time máx' },
];

/**
 * Chips de filtro de SRCH-01.
 *
 * Totalmente controlado: no guarda criterios, los recibe y emite el objeto
 * completo de criterios. `activeChips` y `withoutChip` viven en la capa de
 * datos; aquí solo se pintan y se emiten eventos.
 */
export function FilterChips({ criteria, onChange }: FilterChipsProps) {
  const [open, setOpen] = useState(false);
  const [field, setField] = useState<ChipKey>('partNumber');
  const [value, setValue] = useState('');

  const chips = activeChips(criteria);

  const toggleForm = () => {
    if (!open) {
      setField('partNumber');
      setValue('');
    }
    setOpen((prev) => !prev);
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = value.trim();
    if (!trimmed) return;

    const next: SearchCriteria = { ...criteria };
    switch (field) {
      case 'partNumber':
        next.partNumber = trimmed;
        break;
      case 'brand':
        next.brand = trimmed;
        break;
      case 'minQuantity': {
        const n = Number(trimmed);
        if (!Number.isFinite(n) || n < 0) return;
        next.minQuantity = n;
        break;
      }
      case 'zone': {
        if (!ZONES.includes(trimmed as Zone)) return;
        next.zone = trimmed as Zone;
        break;
      }
      case 'maxLeadTimeDays': {
        const n = Number(trimmed);
        if (!Number.isFinite(n) || n < 0) return;
        next.maxLeadTimeDays = n;
        break;
      }
    }

    onChange(next);
    setValue('');
    setOpen(false);
  };

  return (
    <div className={styles.chipsRow}>
      {chips.map((chip) => (
        <span key={chip.key} className={styles.chip}>
          <span className={styles.chipLabel}>{chip.label}</span>
          {chip.value}
          <button
            type="button"
            className={styles.chipX}
            aria-label={`Quitar filtro ${chip.label}`}
            onClick={() => onChange(withoutChip(criteria, chip.key))}
          >
            ×
          </button>
        </span>
      ))}

      <button type="button" className={styles.chipAdd} onClick={toggleForm}>
        + Filtro
      </button>

      {open && (
        <form className={styles.addForm} onSubmit={handleSubmit}>
          <select
            className={styles.fieldSelect}
            aria-label="Campo"
            value={field}
            onChange={(e) => {
              setField(e.target.value as ChipKey);
              setValue('');
            }}
          >
            {FIELD_OPTIONS.map((opt) => (
              <option key={opt.key} value={opt.key}>
                {opt.label}
              </option>
            ))}
          </select>

          {field === 'zone' ? (
            <select
              className={styles.valueSelect}
              aria-label="Valor"
              value={value}
              onChange={(e) => setValue(e.target.value)}
            >
              <option value="" disabled>
                Elige zona…
              </option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {ZONE_LABELS[z]}
                </option>
              ))}
            </select>
          ) : (
            <input
              className={styles.valueInput}
              aria-label="Valor"
              type={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 'number' : 'text'}
              min={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 0 : undefined}
              placeholder={
                field === 'partNumber'
                  ? '6205-2RS'
                  : field === 'brand'
                    ? 'SKF'
                    : field === 'minQuantity'
                      ? '500'
                      : '7'
              }
              value={value}
              onChange={(e) => setValue(e.target.value)}
            />
          )}

          <button type="submit" className={styles.addBtn}>
            Añadir
          </button>
        </form>
      )}
    </div>
  );
}

