import {
  ageLabel,
  ageLevel,
  countryName,
  daysSince,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type AgeLevel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

interface Column {
  key: SortColumn | null;
  label: string;
  srOnly?: boolean;
}

/** Las diez columnas en el orden fijo e inamovible de la spec §7. */
const COLUMNS: Column[] = [
  { key: null, label: 'Seleccionar', srOnly: true },
  { key: null, label: 'Referencia' },
  { key: 'brand', label: 'Marca' },
  { key: 'quantity', label: 'Cantidad' },
  { key: 'leadTime', label: 'Plazo' },
  { key: null, label: 'Empresa' },
  { key: 'country', label: 'País' },
  { key: 'age', label: 'Antigüedad' },
  { key: 'favorites', label: 'Favoritos' },
  { key: null, label: 'Acciones', srOnly: true },
];

const AGE_CLASSES: Record<AgeLevel, string> = {
  fresh: '',
  stale: styles.ageStale,
  critical: styles.ageCritical,
};

interface ResultsTableProps {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  onContact: (orgId: string) => void;
}

/**
 * Tabla de resultados de SRCH-01.
 *
 * Presentacional: pinta las filas en el orden exacto en que las recibe (ordenar
 * es de la pantalla) y no carga datos. El estado vacío de la spec §6 vive aquí,
 * dentro de la `<table>`, en su propia fila con `colSpan`.
 */
export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now,
  onSort,
  onToggleRow,
  onToggleFavorite,
  onConsult,
  onContact,
}: ResultsTableProps) {
  return (
    <table className={styles.table}>
      <thead>
        <tr>
          {COLUMNS.map((col) => {
            const sortable = col.key !== null;
            const active = sortable && sort?.column === col.key;
            const ariaSort = active && sort ? (sort.direction === 'asc' ? 'ascending' : 'descending') : undefined;
            const headerClass = sortable
              ? `${styles.sortable}${active && sort ? ` ${sort.direction === 'asc' ? styles.sortAsc : styles.sortDesc}` : ''}`
              : undefined;

            return (
              <th key={col.label} aria-sort={ariaSort} className={headerClass}>
                {sortable && col.key !== null ? (
                  <button
                    type="button"
                    className={styles.sortBtn}
                    onClick={() => onSort(col.key as SortColumn)}
                  >
                    {col.label}
                    {active && sort ? (sort.direction === 'asc' ? ' ↑' : ' ↓') : ''}
                  </button>
                ) : col.srOnly ? (
                  <span className={styles.srOnly}>{col.label}</span>
                ) : (
                  col.label
                )}
              </th>
            );
          })}
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 ? (
          <tr>
            <td colSpan={10} className={styles.emptyCell}>
              No hemos encontrado stock con estos filtros.
            </td>
          </tr>
        ) : (
          rows.map((row) => {
            const days = daysSince(row.lastUploadAt, now);
            const level = ageLevel(days);
            const ageCls = AGE_CLASSES[level];
            const qtyOk = meetsMinQuantity(row.quantity, minQuantity);
            return (
              <tr key={row.id} className={row.consulted ? styles.consulted : undefined}>
                <td className={styles.tdChk}>
                  <input
                    type="checkbox"
                    checked={selected.has(row.id)}
                    aria-label={`Seleccionar ${row.partNumber}`}
                    onChange={() => onToggleRow(row.id)}
                  />
                </td>
                <td>
                  <span className={styles.cellRef}>{row.partNumber}</span>
                </td>
                <td>
                  <span className={styles.brandBadge}>{row.brand}</span>
                </td>
                <td>
                  <span className={`${styles.cellQty} ${qtyOk ? styles.qtyOk : styles.qtyLow}`}>
                    {quantityLabel(row.quantity)}
                  </span>
                </td>
                <td>
                  <span className={styles.cellLead}>{leadTimeLabel(row.leadTimeDays)}</span>
                </td>
                <td>
                  <span className={styles.cellOrg}>{row.orgName}</span>
                </td>
                <td>
                  <span className={styles.countryBadge}>{countryName(row.country)}</span>
                </td>
                <td>
                  <span className={`${styles.cellAge} ${ageCls}`}>{ageLabel(days)}</span>
                </td>
                <td>
                  <button
                    type="button"
                    className={styles.favBtn}
                    aria-pressed={row.isFavorite}
                    aria-label={
                      row.isFavorite ? `Quitar favorito a ${row.orgName}` : `Añadir favorito a ${row.orgName}`
                    }
                    onClick={() => onToggleFavorite(row.orgId)}
                  >
                    <span className={styles.favStar}>★</span>
                    <span className={styles.favCount}>{row.favoriteCount}</span>
                  </button>
                </td>
                <td>
                  <div className={styles.actionsCell}>
                    <button
                      type="button"
                      className={styles.consultBtn}
                      disabled
                      title={
                        row.consulted
                          ? "Ya consultada anteriormente · usa 'Consultar seleccionados' para reenviar"
                          : "Marca la fila y usa 'Consultar seleccionados'"
                      }
                      onClick={() => onConsult(row.id)}
                    >
                      Consultar
                    </button>
                    <button
                      type="button"
                      className={styles.contactBtn}
                      disabled
                      title="Contactar con distribuidores está fuera de alcance en esta versión"
                      onClick={() => onContact(row.orgId)}
                    >
                      Contactar
                    </button>
                  </div>
                </td>
              </tr>
            );
          })
        )}
      </tbody>
    </table>
  );
}

