} from '../../lib/search';
import type { MemberProfile } from '../../lib/session';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

const ERROR_MESSAGE = 'No se pudieron cargar los resultados. Inténtalo de nuevo.';
const CAPPED_MESSAGE = 'Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.';

interface SearchResultsProps {
  profile: MemberProfile;
  now?: Date;
  veraCriteria?: SearchCriteria | null;
}

/**
 * SRCH-01 · Panel de Resultados de Búsqueda.
 *
 * Es la pantalla, no un componente de presentación: posee criterios, orden,
 * selección, página cargada, carga y error. La tabla y los chips son
 * presentacionales y reciben todo por props.
 *
 * F-118: `veraCriteria` forma parte de la firma pública porque App.tsx ya la
 * pasa, pero el cableado VERA <-> chips es del día 9 y sigue en out_of_scope.
 * Se recibe y se ignora a propósito: no cambia nada de esta tarea.
 */
export function SearchResults({ profile, now, veraCriteria }: SearchResultsProps) {
  void veraCriteria;

  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [page, setPage] = useState<SearchPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const sendingRef = useRef(false);

  const load = useCallback(
    async (c: SearchCriteria) => {
      setLoading(true);
      setError(null);
      try {
        const next = await fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria: c });
        setPage(next);
      } catch {
        setError(ERROR_MESSAGE);
      } finally {
        setLoading(false);
      }
    },
    [profile.orgId, profile.id],
  );

  useEffect(() => {
    void load(criteria);
  }, [load, criteria]);

  // Al cambiar los criterios, la selección anterior apunta a líneas que pueden
  // haber dejado de estar en la tabla: se limpia para que el lote no mienta.
  useEffect(() => {
    setSelected(new Set());
  }, [criteria]);

  const rows = useMemo(() => (page ? sortRows(page.rows, sort) : []), [page, sort]);

  const withStock = useMemo(
    () => (page ? page.rows.filter((r) => meetsMinQuantity(r.quantity, criteria.minQuantity)).length : 0),
    [page, criteria.minQuantity],
  );

  const allSelected = page !== null && page.rows.length > 0 && page.rows.every((r) => selected.has(r.id));
  const nowValue = useMemo(() => now ?? new Date(), [now]);

  const handleCriteriaChange = (next: SearchCriteria) => setCriteria(next);

  const handleSort = (column: SortColumn) => setSort((prev) => nextSort(prev, column));

  const handleToggleRow = (lineId: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(lineId)) {
        next.delete(lineId);
      } else {
        next.add(lineId);
      }
      return next;
    });
  };

  const handleToggleSelectAll = () => {
    if (!page) return;
    setSelected(allSelected ? new Set() : new Set(page.rows.map((r) => r.id)));
  };

  const handleConsultSelected = async () => {
    if (sendingRef.current) return;
    if (!page) return;

    const selectedRows = page.rows.filter((r) => selected.has(r.id));
    if (selectedRows.length === 0) return;

    const pending = selectedRows.filter((r) => !r.consulted);
    const omitidas = selectedRows.length - pending.length;

    if (pending.length === 0) {
      setNotice(consultSummary([], omitidas));
      setSelected(new Set());
      return;
    }

    sendingRef.current = true;
    setSending(true);
    try {
      const resultados = (await sendInquiries(
        pending.map((r) => ({
          inventoryLineId: r.id,
          distributorOrgId: r.orgId,
          quantity: r.quantity,
        })) as unknown as Parameters<typeof sendInquiries>[0],
      )) as InquirySendResult[];

      setNotice(consultSummary(resultados, omitidas));
      setSelected(new Set());
      // El usuario permanece en SRCH-01: se vuelve a leer la tabla para que el
      // estado "ya consultada" salga de la base, no de un simulacro en cliente.
      await load(criteria);
    } catch {
      setNotice('No se pudieron enviar las consultas. Inténtalo de nuevo.');
    } finally {
      sendingRef.current = false;
      setSending(false);
    }
  };

  const handleToggleFavorite = async (orgId: string) => {
    if (!page) return;
    const row = page.rows.find((r) => r.orgId === orgId);
    if (!row) return;

    try {
      await toggleFavorite(profile.id, orgId, !row.isFavorite);
      // F-118: el recuento agregado lo mantiene la base; se relee, no se
      // incrementa a ojo en el cliente.
      await load(criteria);
    } catch {
      setNotice('No se pudo actualizar el favorito. Inténtalo de nuevo.');
    }
  };

  return (
    <div className={styles.screen}>
      <div className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</div>
      <h1 className={styles.title}>Resultados de búsqueda</h1>

      <FilterChips criteria={criteria} onChange={handleCriteriaChange} />

      <div className={styles.metabar}>
        <div className={styles.metaCount}>
          {page ? metaCounterLabel(page.total, withStock, criteria.minQuantity) : '\u00A0'}
        </div>
        <button type="button" className={styles.selAll} onClick={handleToggleSelectAll}>
          {allSelected ? 'Deseleccionar todos' : 'Seleccionar todos'}
        </button>
        <button
          type="button"
          className={styles.consultSel}
          disabled={selected.size === 0 || sending}
          onClick={() => void handleConsultSelected()}
        >
          Consultar seleccionados
        </button>
        <button
          type="button"
          className={styles.watcher}
          disabled
          title="Los watchers llegarán en una próxima versión"
        >
          <i className="ti ti-bell-plus" aria-hidden="true" />
          Crear watcher con estos criterios
        </button>
      </div>

      <div className={styles.resultsArea} aria-busy={loading ? 'true' : 'false'}>
        {!error && page?.capped && <div className={styles.capped}>{CAPPED_MESSAGE}</div>}
        {notice && (
          <div className={styles.notice} role="status">
            {notice}
          </div>
        )}

        {error ? (
          <div className={styles.error} role="alert">
            <p>{error}</p>
            <button type="button" className={styles.reload} onClick={() => void load(criteria)}>
              Reintentar
            </button>
          </div>
        ) : loading ? (
          <div className={styles.spinner} role="status">
            <i className="ti ti-loader" aria-hidden="true" />
            Buscando…
          </div>
        ) : (
          <div className={styles.tableOuter}>
            <ResultsTable
              rows={rows}
              sort={sort}
              selected={selected}
              minQuantity={criteria.minQuantity}
              now={nowValue}
              onSort={handleSort}
              onToggleRow={handleToggleRow}
              onToggleFavorite={handleToggleFavorite}
              onConsult={() => {}}
              onContact={() => {}}
            />
          </div>
        )}
      </div>
    </div>
  );
}
